import time

def busca_binaria(lista, alvoDesejado):
    inicio = 0
    fim = len(lista) - 1
    comparacoes = 0

    while inicio <= fim:
        comparacoes += 1
        meio = (inicio + fim) // 2
        if lista[meio] == alvoDesejado:
            break
        elif lista[meio] < alvoDesejado:
            inicio = meio + 1
        else:
            fim = meio - 1

    print(f"Total de comparações: {comparacoes}")
    return meio

